<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$d=body();required($d,['id','name','cost_price','selling_price']);$s=db()->prepare('SELECT user_id FROM products WHERE id=?');$s->execute([$d['id']]);$p=$s->fetch();if(!$p)fail('Product not found',404);if($p['user_id']!=$u['id']&&$u['role']!=='admin')fail('Not your product',403);$q=db()->prepare('UPDATE products SET name=?,brand=?,category=?,cost_price=?,selling_price=?,condition_status=?,description=? WHERE id=?');$q->execute([$d['name'],$d['brand']??null,$d['category']??'phone',$d['cost_price'],$d['selling_price'],$d['condition_status']??'used',$d['description']??null,$d['id']]);out(['success'=>true,'message'=>'Product updated']);
